const ctx=$input.first().json; const t=((ctx.mensaje&&ctx.mensaje.texto)||'').trim(); const k=t.toLowerCase();
const mapa={OP_PEDIDO:'pedido',OP_CATALOGO:'catalogo',OP_ESTADO:'estado_pedido',OP_FAQ:'faq_pedir',OP_PERSONA:'persona',MENU:'menu','menu':'menu','menú':'menu'};
let opcion=mapa[t]||mapa[k]||null;
if(!opcion&&ctx.conversacion&&ctx.conversacion.estado==='FAQ')opcion='faq';
return [{json:{...ctx,opcion,texto_libre:!opcion}}];

const ctx=$('Preparar IA (intención)').first().json; const r=$input.first().json;
const m={ver_catalogo:'catalogo',estado_pedido:'estado_pedido',pregunta_faq:'faq',hacer_pedido:'pedido',hablar_persona:'persona',ajeno:'ajeno'};
const op=(r.confianza>=0.6&&m[r.intencion])?m[r.intencion]:'no_entendido';
return [{json:{...ctx,opcion:op}}];

const rows=$input.all().map(i=>i.json).filter(r=>r.nombre);
if(!rows.length)return [{json:{texto_catalogo:'Por ahora no hay productos cargados.'}}];
const g={};rows.forEach(r=>{const c=r.categoria||'Otros';(g[c]=g[c]||[]).push(r)});
let t='*Catálogo*\n';
for(const c in g){t+='\n*'+c+'*\n';g[c].forEach(p=>{t+='• '+p.nombre+' - $'+Number(p.precio).toLocaleString('es-CO')+(p.disponible?'':' (agotado)')+'\n'})}
return [{json:{texto_catalogo:t+'\n¿Qué deseas hacer ahora?'}}];

const ctx=$('Entrada').first().json;
const r=$input.first().json;
return [{json:{...ctx,wa:{tipo:'botones',texto:r.texto_catalogo,botones:[{id:'OP_PEDIDO',titulo:'Hacer un pedido'},{id:'MENU',titulo:'Volver al menú'}]}}}];

const rows=$input.all().map(i=>i.json).filter(r=>r.numero);
const t=rows.length?'Tus pedidos:
'+rows.map(p=>'#'+p.numero+': '+p.estado).join('
'):'No encontré pedidos a tu nombre.';
return [{json:{texto_estado:t+'
Escribe menú para volver.'}}];

const ctx=$('Entrada').first().json;
const r=$input.first().json;
return [{json:{...ctx,wa:{tipo:'texto',texto:r.respuesta+'\nEscribe menú para volver.'}}}];
